import static org.junit.Assert.*;

public class TokenBuffer_writeNumber_TriageGen0Test {

    private TokenBuffer tokenBuffer;
    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // Using the constructor that takes an ObjectCodec
        tokenBuffer = new TokenBuffer(mapper);
    }

    /**
     * Tests that passing null to writeNumber calls writeNull().
     * This covers the if (v == null) branch.
     */
    @Test
    public void testWriteNumber_Null() throws IOException {
        tokenBuffer.writeNumber((BigInteger) null);

        // Verify the token is indeed VALUE_NULL
        Assert.assertEquals(JsonToken.VALUE_NULL, tokenBuffer.firstToken());
    }






}
